package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {
    public void testEscapeJavaScript() {
        String input = "<script>alert('aaa');</script>";
        String escaped = StringEscapeUtils.escapeJavaScript(input);

        // The reporter says '/' should be escaped to '\/'
        // The report specifically mentions the closing tag: <https://script>
        // We check if the escaped string contains the escaped slash.

        assertTrue("The forward slash should be escaped to <redacted URL>", escaped.indexOf("<" + "\\" + "/script>") != -1);
    }
}

