package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {
    public void testEscapeJavaScript() {
        String input = "<script>alert('aaa');</script>";
        String escaped = StringEscapeUtils.escapeEcmaScript(input);
        // The reporter says '/' should be escaped to '\/'
        // So '<script>' should become '<\u002fscript>' or similar.
        // The report specifically mentions the closing tag: <https://script>

        // In Commons Lang 3, escapeJavaScript was renamed to escapeEcmaScript.
        // However, the report is from 2007, so it might be using the old name.
        // The runner translates org.apache.commons.lang to org.apache.commons.lang3.
        // I will try escapeEcmaScript first as it is the modern equivalent.
        // If it doesn't compile, I'll try escapeJavaScript.

        assertTrue("The forward slash should be escaped", escaped.indexOf("<" + "\\" + "/script>") != -1);
    }
}

